'use client';

/*
 * Consent preferences (Radix UI), "pelure" style — generated by `zeste add --style pelure`, yours to edit.
 * Nothing is pre-checked: a service the user has not chosen is treated as refused.
 */
import { Dialog, Label, Switch } from 'radix-ui';
import { useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import './theme.css';

const focus = 'focus-visible:outline-[3px] focus-visible:outline-offset-[3px] focus-visible:outline-(--zeste-ink)';
const button = `inline-flex items-center justify-center rounded-[10px] border-[2.5px] border-(--zeste-ink) bg-(--zeste-card) px-[18px] py-2.5 text-sm font-bold text-(--zeste-ink) shadow-[4px_4px_0_var(--zeste-ink)] transition-transform active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--zeste-ink)] ${focus}`;
const save = `inline-flex items-center justify-center rounded-[10px] border-[2.5px] border-(--zeste-ink) bg-(--zeste-paper) px-[18px] py-2.5 text-sm font-bold text-(--zeste-ink) shadow-[4px_4px_0_var(--zeste-ink)] transition-transform active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--zeste-ink)] ${focus}`;

export function CookiePreferences() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <Dialog.Root open={zeste.preferencesOpen} onOpenChange={zeste.setPreferencesOpen}>
      <Dialog.Portal>
        <Dialog.Overlay data-zeste-skin="pelure" className="fixed inset-0 z-50 bg-(--zeste-scrim)" />
        <Dialog.Content
          data-zeste-skin="pelure"
          className="fixed top-1/2 left-1/2 z-50 grid max-h-[85vh] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 overflow-y-auto rounded-[14px] border-[3px] border-(--zeste-ink) bg-(--zeste-card) p-6 text-(--zeste-ink) shadow-[8px_8px_0_var(--zeste-ink)]"
        >
          <Dialog.Title className="pr-8 text-2xl font-extrabold tracking-tight">{t.title}</Dialog.Title>
          <Dialog.Description className="text-sm leading-relaxed font-medium">{t.disclaimer}</Dialog.Description>

          {zeste.categories.map((category) => (
            <section
              key={category.key}
              className="grid gap-2 border-t-[2.5px] border-(--zeste-ink) pt-3"
              aria-labelledby={`zeste-category-${category.key}`}
            >
              <h3 id={`zeste-category-${category.key}`} className="text-sm font-bold">
                {t.categories[category.key]?.title ?? category.key}
              </h3>
              <p className="text-sm">{t.categories[category.key]?.details}</p>
              <ul className="grid gap-3 pt-1">
                {category.services.map((service) => (
                  <li key={service.key} className="flex items-center justify-between gap-4">
                    <div className="text-sm">
                      <Label.Root htmlFor={`zeste-service-${service.key}`} className="font-medium">
                        {service.name}
                      </Label.Root>
                      {service.privacyUrl && (
                        <a
                          href={service.privacyUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="block underline underline-offset-2"
                        >
                          {t.privacyUrl}{' '}
                          <span className="sr-only">
                            {service.name} {t.newWindow}
                          </span>
                        </a>
                      )}
                    </div>
                    <Switch.Root
                      id={`zeste-service-${service.key}`}
                      checked={zeste.draft[service.key] ?? false}
                      onCheckedChange={(checked) => zeste.setDraft(service.key, checked)}
                      className={`inline-flex h-[28px] w-12 shrink-0 cursor-pointer items-center rounded-[8px] border-[2.5px] border-(--zeste-ink) bg-white p-[2px] transition data-[state=checked]:bg-(--zeste-paper) ${focus}`}
                    >
                      <Switch.Thumb className="block size-[18px] rounded-[4px] bg-(--zeste-ink) transition data-[state=checked]:translate-x-[20px]" />
                    </Switch.Root>
                  </li>
                ))}
              </ul>
            </section>
          ))}

          {zeste.exempt.length > 0 && (
            <p className="border-t-[2.5px] border-(--zeste-ink) pt-3 text-sm">
              <span className="font-bold">{t.mandatoryTitle}</span> :{' '}
              {zeste.exempt.map((s) => s.name).join(', ')}
            </p>
          )}

          <div className="flex flex-wrap items-center gap-2 pt-2">
            <button type="button" className={button} {...zeste.actions.denyAll}>
              {t.denyAll}
            </button>
            <button type="button" className={button} {...zeste.actions.acceptAll}>
              {t.acceptAll}
            </button>
            <button type="button" className={`${save} ml-auto`} {...zeste.actions.savePreferences}>
              {t.save}
            </button>
          </div>

          <Dialog.Close
            className={`absolute top-5 right-5 grid size-8 place-items-center rounded-[8px] border-[2.5px] border-(--zeste-ink) bg-(--zeste-paper) font-bold ${focus}`}
            aria-label={t.close}
          >
            <span aria-hidden="true">✕</span>
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
